//! Emit `include/dregg_sig.h` from the crate's own constants.
//!
//! The header is generated, never hand-edited: every size constant in it is read from
//! [`dregg_sig_ffi::api`], so a header that disagrees with the library cannot be produced.
//!
//! ```sh
//! cargo run -p dregg-sig-ffi --bin dregg-sig-header > crates/ffi/include/dregg_sig.h
//! ```

use dregg_sig_ffi::api;

fn main() {
    let mut out = String::new();
    out.push_str(
        "/* dregg_sig.h - generated by `dregg-sig-header`; do not edit by hand.\n\
         *\n\
         * C ABI for the stateless FIPS 205 SLH-DSA surface of dregg-sig-core.\n\
         *\n\
         * Conventions:\n\
         *   - the caller owns every buffer; this library never allocates for you;\n\
         *   - every length is explicit, and every output length is reported back through\n\
         *     a `size_t *written` out-parameter, also when the buffer is too small;\n\
         *   - output buffers must not overlap any input buffer or each other;\n\
         *   - failure is an integer code (see the DREGG_SIG_ERR_* constants), never a\n\
         *     string and never a panic;\n\
         *   - secret-key output buffers are wiped on every error path.\n\
         */\n\n\
         #ifndef DREGG_SIG_H\n#define DREGG_SIG_H\n\n\
         #include <stddef.h>\n#include <stdint.h>\n\n\
         #ifdef __cplusplus\nextern \"C\" {\n#endif\n\n",
    );

    out.push_str("/* Parameter-set identifiers. */\n");
    for (name, id) in [
        ("DREGG_SIG_PARAM_128S", api::PARAM_128S),
        ("DREGG_SIG_PARAM_128F", api::PARAM_128F),
        ("DREGG_SIG_PARAM_192S", api::PARAM_192S),
        ("DREGG_SIG_PARAM_192F", api::PARAM_192F),
        ("DREGG_SIG_PARAM_256S", api::PARAM_256S),
        ("DREGG_SIG_PARAM_256F", api::PARAM_256F),
    ] {
        out.push_str(&format!("#define {name} {id}u\n"));
    }

    out.push_str("\n/* Error codes. */\n");
    for (name, code) in [
        ("DREGG_SIG_OK", api::OK),
        ("DREGG_SIG_ERR_NULL_POINTER", api::ERR_NULL_POINTER),
        ("DREGG_SIG_ERR_BUFFER_TOO_SMALL", api::ERR_BUFFER_TOO_SMALL),
        ("DREGG_SIG_ERR_INVALID_PARAM", api::ERR_INVALID_PARAM),
        ("DREGG_SIG_ERR_INVALID_LENGTH", api::ERR_INVALID_LENGTH),
        ("DREGG_SIG_ERR_CONTEXT_TOO_LONG", api::ERR_CONTEXT_TOO_LONG),
        ("DREGG_SIG_ERR_VERIFY_FAILED", api::ERR_VERIFY_FAILED),
        ("DREGG_SIG_ERR_PANIC", api::ERR_PANIC),
        ("DREGG_SIG_ERR_INTERNAL", api::ERR_INTERNAL),
    ] {
        out.push_str(&format!("#define {name} ({code})\n"));
    }

    out.push_str(
        "\n/* Upper bounds over all six parameter sets, for sizing buffers without guessing. */\n",
    );
    out.push_str(&format!(
        "#define DREGG_SIG_MAX_PK_BYTES {}\n",
        api::MAX_PK_BYTES
    ));
    out.push_str(&format!(
        "#define DREGG_SIG_MAX_SK_BYTES {}\n",
        api::MAX_SK_BYTES
    ));
    out.push_str(&format!(
        "#define DREGG_SIG_MAX_SIG_BYTES {}\n",
        api::MAX_SIG_BYTES
    ));
    out.push_str(&format!(
        "#define DREGG_SIG_MAX_CTX_BYTES {}\n",
        api::MAX_CTX_BYTES
    ));

    out.push_str("\n/* Exact per-set sizes, so a caller can size a buffer for one set. */\n");
    for (label, id) in [
        ("128S", api::PARAM_128S),
        ("128F", api::PARAM_128F),
        ("192S", api::PARAM_192S),
        ("192F", api::PARAM_192F),
        ("256S", api::PARAM_256S),
        ("256F", api::PARAM_256F),
    ] {
        out.push_str(&format!(
            "#define DREGG_SIG_{label}_PK_BYTES {}\n",
            api::pk_bytes(id).unwrap()
        ));
        out.push_str(&format!(
            "#define DREGG_SIG_{label}_SK_BYTES {}\n",
            api::sk_bytes(id).unwrap()
        ));
        out.push_str(&format!(
            "#define DREGG_SIG_{label}_SIG_BYTES {}\n",
            api::sig_bytes(id).unwrap()
        ));
    }

    out.push_str(
        "\n/* Exact sizes for a parameter-set identifier, or 0 for an unknown identifier. */\n\
         size_t dregg_sig_pk_bytes(uint32_t param);\n\
         size_t dregg_sig_sk_bytes(uint32_t param);\n\
         size_t dregg_sig_sig_bytes(uint32_t param);\n\n\
         /* Static, NUL-terminated description of an error code. Never allocates. */\n\
         const char *dregg_sig_strerror(int code);\n\n\
         /* Overwrite `len` bytes at `buf` with zeros. */\n\
         void dregg_sig_wipe(uint8_t *buf, size_t len);\n\n\
         /* SHAKE256 with a 32-byte output. */\n\
         int dregg_sig_shake256_32(const uint8_t *input, size_t input_len,\n\
         \x20                         uint8_t *out, size_t out_len, size_t *written);\n\n\
         /* Generate a keypair from explicit (SK.seed, SK.prf, PK.seed) components.\n\
          * Writes 4*n secret-key bytes and 2*n public-key bytes. On any error,\n\
          * including a public-key buffer that is too small, the secret-key output\n\
          * buffer is wiped before returning. */\n\
         int dregg_sig_keygen(uint32_t param,\n\
         \x20                    const uint8_t *sk_seed, size_t sk_seed_len,\n\
         \x20                    const uint8_t *sk_prf, size_t sk_prf_len,\n\
         \x20                    const uint8_t *pk_seed, size_t pk_seed_len,\n\
         \x20                    uint8_t *sk_out, size_t sk_out_len, size_t *sk_written,\n\
         \x20                    uint8_t *pk_out, size_t pk_out_len, size_t *pk_written);\n\n\
         /* Generate a keypair from one master seed. On any error the secret-key\n\
          * output buffer is wiped before returning. */\n\
         int dregg_sig_keygen_from_seed(uint32_t param,\n\
         \x20                              const uint8_t *seed, size_t seed_len,\n\
         \x20                              uint8_t *sk_out, size_t sk_out_len, size_t *sk_written,\n\
         \x20                              uint8_t *pk_out, size_t pk_out_len, size_t *pk_written);\n\n\
         /* Derive the public key from a canonical secret key. */\n\
         int dregg_sig_pk_from_sk(uint32_t param,\n\
         \x20                        const uint8_t *sk, size_t sk_len,\n\
         \x20                        uint8_t *pk_out, size_t pk_out_len, size_t *pk_written);\n\n\
         /* Sign `msg` under `ctx` (pure SLH-DSA, deterministic). */\n\
         int dregg_sig_sign(uint32_t param,\n\
         \x20                  const uint8_t *sk, size_t sk_len,\n\
         \x20                  const uint8_t *msg, size_t msg_len,\n\
         \x20                  const uint8_t *ctx, size_t ctx_len,\n\
         \x20                  uint8_t *sig_out, size_t sig_out_len, size_t *sig_written);\n\n\
         /* Verify a signature. Returns DREGG_SIG_OK when it verifies and\n\
          * DREGG_SIG_ERR_VERIFY_FAILED when it does not. */\n\
         int dregg_sig_verify(uint32_t param,\n\
         \x20                    const uint8_t *pk, size_t pk_len,\n\
         \x20                    const uint8_t *msg, size_t msg_len,\n\
         \x20                    const uint8_t *ctx, size_t ctx_len,\n\
         \x20                    const uint8_t *sig, size_t sig_len);\n\n\
         #ifdef __cplusplus\n}\n#endif\n\n#endif /* DREGG_SIG_H */\n",
    );

    print!("{out}");
}
